CREATE OR REPLACE VIEW public.feed_items AS SELECT id, title, url, source_name, published_at, summary, why_it_matters, category, relevance, region, geo_scope, geo_region, admin_area, locality FROM public.news_items WHERE relevance >= 3 AND is_primary IS NOT FALSE AND COALESCE(published_at, created_at) > (now() - interval '14 days') ORDER BY COALESCE(published_at, created_at) DESC;
